import { useState } from 'react';
import { Calendar, MapPin, Clock } from 'lucide-react';
import { useNavigate, useOutletContext } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import Modal from '../components/Modal';

export default function Dashboard() {
  const navigate = useNavigate();
  const { t, upcomingAppointments, setUpcomingAppointments } = useOutletContext();
  const [bookingModalOpen, setBookingModalOpen] = useState(false);
  const [clinicsModalOpen, setClinicsModalOpen] = useState(false);
  const [selectedDoctor, setSelectedDoctor] = useState(null);
  const [bookingDetails, setBookingDetails] = useState({ date: '', time: '10:00 AM' });
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  const doctorsList = [
    { name: 'Mugisha Alice', spec: 'Pediatric', exp: '12 years experience', fee: '$25', img: 'data:image/jpeg;base64,', online: true },
    { name: 'Rugango Kevin', spec: 'Surgical', exp: '10 years experience', fee: '$35', img: 'data:image/jpeg;base64,', online: false },
    { name: 'Uwase Solange', spec: 'Gastroenterology', exp: '7 years experience', fee: '$15', img: 'data:image/jpeg;base64,', online: true },
    { name: 'Habimana Jean', spec: 'Cardiology', exp: '15 years experience', fee: '$50', img: 'data:image/jpeg;base64,', online: true },
    { name: 'Iradukunda Diane', spec: 'Neurology', exp: '8 years experience', fee: '$40', img: 'data:image/jpeg;base64,', online: false },
    { name: 'Shyaka Patrick', spec: 'Orthopedics', exp: '11 years experience', fee: '$30', img: 'data:image/jpeg;base64,', online: true }
  ];

  const categories = ['All', 'Pediatric', 'Surgical', 'Gastroenterology', 'Cardiology', 'Neurology', 'Orthopedics'];

  const filteredDoctors = doctorsList.filter(doc => {
    const matchesSearch = doc.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      doc.spec.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = activeCategory === 'All' || doc.spec === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const handleBookClick = (doctorName) => {
    setSelectedDoctor(doctorName);
    setBookingDetails({ date: '', time: '10:00 AM' });
    setBookingModalOpen(true);
  };

  const completeBooking = () => {
    if (!bookingDetails.date || !bookingDetails.time) {
      toast.error('Please select a valid date and time.');
      return;
    }

    const dateObj = new Date(bookingDetails.date);
    const dayStr = dateObj.toLocaleDateString('en-US', { weekday: 'short' });
    const dayNum = dateObj.getDate();

    const timeParts = bookingDetails.time.split(' ');
    const [h, m] = timeParts[0].split(':');
    let minutes = parseInt(m) + 30;
    let hour = parseInt(h);
    let ampm = timeParts[1];
    if (minutes >= 60) {
      minutes -= 60;
      hour += 1;
    }
    if (hour > 12) hour -= 12;
    const endTime = `${hour}:${minutes === 0 ? '00' : minutes} ${ampm}`;

    const newAppt = {
      id: Date.now(),
      doctor: `Dr. ${selectedDoctor}`,
      day: dayStr,
      date: dayNum.toString(),
      time: `${bookingDetails.time} - ${endTime}`,
      color: 'var(--text-main)',
      bg: '#F3F4F6'
    };

    setUpcomingAppointments([newAppt, ...upcomingAppointments]);
    toast.success(`Successfully booked appointment with ${selectedDoctor} on ${bookingDetails.date} at ${bookingDetails.time}`);
    setBookingModalOpen(false);
  };

  const hoursSaved = (upcomingAppointments.length * 1.8 + 14.5).toFixed(1);

  return (
    <div>
      {/* Quick Stats Row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '24px', marginBottom: '32px' }}>
        <button
          className="card"
          style={{ marginBottom: 0, padding: '20px', display: 'flex', alignItems: 'center', gap: '16px', cursor: 'pointer', border: '1px solid var(--border)', transition: 'all 0.2s', width: '100%', textAlign: 'left', background: 'white' }}
          onMouseEnter={(e) => e.currentTarget.style.borderColor = 'var(--primary)'}
          onMouseLeave={(e) => e.currentTarget.style.borderColor = 'var(--border)'}
          onClick={() => navigate('/my-availability')}
        >
          <div>
            <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>{t.upcomingAppointments}</div>
            <div style={{ fontSize: '20px', fontWeight: 700 }}>{upcomingAppointments.length}</div>
          </div>
        </button>

        <div className="card" style={{ marginBottom: 0, padding: '20px', display: 'flex', alignItems: 'center', gap: '16px' }}>
          <div>
            <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>Hours Saved</div>
            <div style={{ fontSize: '20px', fontWeight: 700 }}>{hoursSaved}h</div>
          </div>
        </div>

        <button
          className="card"
          style={{ marginBottom: 0, padding: '20px', display: 'flex', alignItems: 'center', gap: '16px', cursor: 'pointer', border: '1px solid var(--border)', transition: 'all 0.2s', width: '100%', textAlign: 'left', background: 'white' }}
          onMouseEnter={(e) => e.currentTarget.style.borderColor = 'var(--primary)'}
          onMouseLeave={(e) => e.currentTarget.style.borderColor = 'var(--border)'}
          onClick={() => setClinicsModalOpen(true)}
        >
          <div>
            <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>Nearby Clinics</div>
            <div style={{ fontSize: '20px', fontWeight: 700 }}>12</div>
          </div>
        </button>
      </div>

      <div style={{ display: 'flex', gap: '24px', marginBottom: '32px' }}>
        {/* Banner */}
        <div style={{
          flex: 2,
          background: 'linear-gradient(135deg, #3DA1B6 0%, #2A8296 100%)',
          borderRadius: 'var(--radius-lg)',
          padding: '40px',
          color: 'white',
          position: 'relative',
          overflow: 'hidden',
          boxShadow: '0 10px 25px rgba(61, 161, 182, 0.25)'
        }}>
          <div style={{ position: 'absolute', right: '-10%', top: '-20%', width: '300px', height: '300px', border: '2px solid rgba(255,255,255,0.05)', borderRadius: '50%' }}></div>
          <div style={{ position: 'absolute', right: '5%', top: '10%', width: '200px', height: '200px', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '50%' }}></div>

          <h2 style={{ fontSize: '28px', fontWeight: 700, marginBottom: '12px', whiteSpace: 'pre-line', lineHeight: 1.2 }}>
            {t.bannerTitle}
          </h2>
          <p style={{ opacity: 0.9, marginBottom: '32px', maxWidth: '80%', fontSize: '16px' }}>{t.bannerSub}</p>

          <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
            <button
              className="btn-primary"
              style={{ background: 'white', color: 'var(--primary)', padding: '12px 24px', fontWeight: 600, border: 'none', cursor: 'pointer' }}
              onClick={() => navigate('/online-consult')}
            >
              Start Consultation
            </button>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <div style={{ display: 'flex' }}>
                {[1, 2, 3].map(i => <img key={i} src={`https://i.pravatar.cc/100?img=${i + 10}`} style={{ width: 32, height: 32, borderRadius: '50%', border: '2px solid white', marginLeft: i === 1 ? 0 : -10 }} />)}
              </div>
              <span style={{ fontSize: '14px', fontWeight: 500 }}>{t.onlineDocs}</span>
            </div>
          </div>
        </div>

        {/* Sidebar Column */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '24px' }}>
          {/* Upcoming Appointments */}
          <div className="card" style={{ marginBottom: 0, padding: '24px', maxHeight: '344px', overflowY: 'auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: 600 }}>{t.upcomingAppointments}</h3>
              <button onClick={() => navigate('/patient-records')} style={{ color: 'var(--primary)', fontSize: '13px', fontWeight: 600 }}>{t.viewAll}</button>
            </div>

            {upcomingAppointments.length === 0 ? (
              <p style={{ textAlign: 'center', color: 'var(--text-muted)', fontSize: '14px' }}>No appointments yet.</p>
            ) : upcomingAppointments.map((appt) => (
              <div key={appt.id} style={{ display: 'flex', gap: '12px', marginBottom: '12px', paddingBottom: '12px', borderBottom: '1px solid #F3F4F6' }}>
                <div style={{ background: appt.bg, padding: '8px', borderRadius: '8px', textAlign: 'center', minWidth: '50px' }}>
                  <div style={{ fontSize: '10px', color: appt.color, fontWeight: 700, textTransform: 'uppercase' }}>{appt.day}</div>
                  <div style={{ fontSize: '18px', fontWeight: 800, color: appt.color }}>{appt.date}</div>
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600, fontSize: '14px' }}>{appt.doctor}</div>
                  <div style={{ fontSize: '12px', color: 'var(--text-muted)' }}>{appt.time}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Recommended Doctors Section */}
      <div style={{ marginBottom: '32px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '24px' }}>
          <div>
            <h3 style={{ fontSize: '22px', fontWeight: 700, marginBottom: '8px' }}>{t.recommendedDoctors}</h3>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  style={{
                    padding: '8px 16px', borderRadius: '20px', fontSize: '13px', fontWeight: 500,
                    background: activeCategory === cat ? 'var(--primary)' : 'white',
                    color: activeCategory === cat ? 'white' : 'var(--text-muted)',
                    border: '1px solid ' + (activeCategory === cat ? 'var(--primary)' : 'var(--border)'),
                    transition: 'all 0.2s',
                    cursor: 'pointer'
                  }}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>
          <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <input
              type="text"
              placeholder="Search doctor..."
              className="form-input"
              style={{ width: '240px' }}
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '24px' }}>
          {filteredDoctors.length === 0 ? (
            <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '60px', background: 'white', borderRadius: '16px', border: '1px dashed var(--border)' }}>
              <p style={{ color: 'var(--text-muted)' }}>No doctors found in this category.</p>
            </div>
          ) : filteredDoctors.map((doc, idx) => (
            <div key={idx} className="card" style={{ marginBottom: 0, padding: '24px', transition: 'transform 0.2s, box-shadow 0.2s', cursor: 'default' }}>
              <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
                <div style={{ position: 'relative' }}>
                  <img src={doc.img} style={{ width: 80, height: 80, borderRadius: '16px', objectFit: 'cover' }} />
                  {doc.online && <div style={{ position: 'absolute', bottom: -4, right: -4, width: 14, height: 14, background: '#10B981', border: '2px solid white', borderRadius: '50%' }}></div>}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <h4 style={{ fontWeight: 700, fontSize: '18px' }}>{doc.name}</h4>
                    <span style={{ fontSize: '16px', fontWeight: 700, color: 'var(--primary)' }}>{doc.fee}</span>
                  </div>
                  <p style={{ fontSize: '14px', color: 'var(--text-muted)', marginBottom: '8px' }}>{doc.spec} Specialist</p>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '12px', color: '#F59E0B' }}>
                    {'★'.repeat(5)} <span style={{ color: 'var(--text-muted)', marginLeft: '4px' }}>(4.8)</span>
                  </div>
                </div>
              </div>

              <div style={{ background: '#F9FAFB', borderRadius: '12px', padding: '12px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', fontSize: '13px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                  <Clock size={14} color="var(--text-muted)" />
                  <span>{doc.exp}</span>
                </div>
                <div style={{ fontWeight: 600, color: 'var(--text-main)' }}>Available Today</div>
              </div>

              <button className="btn-primary" style={{ width: '100%', borderRadius: '12px', padding: '12px' }} onClick={() => handleBookClick(doc.name)}>
                {t.bookAppointment}
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Booking Modal */}
      <Modal isOpen={bookingModalOpen} onClose={() => setBookingModalOpen(false)} title={t.schedAppt}>
        <p style={{ color: 'var(--text-muted)', marginBottom: '24px', fontSize: '14px' }}>
          {t.selectDate} <strong style={{ color: 'var(--text-main)' }}>{selectedDoctor}</strong>.
        </p>

        <div style={{ display: 'flex', gap: '16px', marginBottom: '24px' }}>
          <div style={{ flex: 1 }}>
            <label style={{ display: 'block', fontSize: '13px', marginBottom: '8px', fontWeight: 500 }}>{t.date}</label>
            <div style={{ position: 'relative' }}>
              <input
                type="date"
                className="form-input"
                style={{ width: '100%', paddingLeft: '36px' }}
                value={bookingDetails.date}
                onChange={(e) => setBookingDetails({ ...bookingDetails, date: e.target.value })}
              />
              <Calendar size={16} color="var(--text-muted)" style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)' }} />
            </div>
          </div>

          <div style={{ flex: 1 }}>
            <label style={{ display: 'block', fontSize: '13px', marginBottom: '8px', fontWeight: 500 }}>{t.time}</label>
            <div style={{ position: 'relative' }}>
              <select
                className="form-input"
                style={{ width: '100%', paddingLeft: '36px' }}
                value={bookingDetails.time}
                onChange={(e) => setBookingDetails({ ...bookingDetails, time: e.target.value })}
              >
                <option>09:00 AM</option>
                <option>09:30 AM</option>
                <option>10:00 AM</option>
                <option>10:30 AM</option>
                <option>11:00 AM</option>
                <option>12:00 PM</option>
                <option>01:00 PM</option>
                <option>02:30 PM</option>
              </select>
              <Clock size={16} color="var(--text-muted)" style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)' }} />
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', gap: '12px' }}>
          <button className="btn-secondary" style={{ flex: 1, justifyContent: 'center' }} onClick={() => setBookingModalOpen(false)}>{t.cancel}</button>
          <button className="btn-primary" style={{ flex: 1, justifyContent: 'center' }} onClick={completeBooking}>{t.confirmBook}</button>
        </div>
      </Modal>

      {/* Nearby Clinics Modal */}
      <Modal isOpen={clinicsModalOpen} onClose={() => setClinicsModalOpen(false)} title="Nearby Clinics">
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {[
            { name: 'City Health Center', dist: '1.2 miles', open: 'Now' },
            { name: 'Priority Care Plus', dist: '2.5 miles', open: 'Now' },
            { name: 'Wellness Memorial', dist: '3.8 miles', open: 'Mon-Fri' },
            { name: 'Green Path Clinic', dist: '4.2 miles', open: 'Now' },
          ].map((cl, i) => (
            <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '12px', background: '#F9FAFB', borderRadius: '8px', border: '1px solid #E5E7EB' }}>
              <div>
                <div style={{ fontWeight: 600 }}>{cl.name}</div>
                <div style={{ fontSize: '12px', color: 'var(--text-muted)' }}>{cl.dist} away</div>
              </div>
              <div style={{ fontSize: '12px', color: cl.open === 'Now' ? '#059669' : 'var(--text-muted)', fontWeight: 500 }}>{cl.open}</div>
            </div>
          ))}
        </div>
        <button className="btn-primary" style={{ width: '100%', justifyContent: 'center', marginTop: '20px' }} onClick={() => setClinicsModalOpen(false)}>
          Close
        </button>
      </Modal>
    </div>
  );
}
